//
// Given a slot, this function iterates over all of its assigned element and text nodes and returns the concatenated
// HTML as a string. This is useful because we can't use slot.innerHTML as an alternative.
//
export function getInnerHTML(slot: HTMLSlotElement): string {
	const nodes = slot.assignedNodes({ flatten: true });
	let html = "";

	[...nodes].map((node) => {
		if (node.nodeType === Node.ELEMENT_NODE) {
			html += (node as HTMLElement).outerHTML;
		}

		if (node.nodeType === Node.TEXT_NODE) {
			html += node.textContent;
		}
	});

	return html;
}

//
// Given a slot, this function iterates over all of its assigned text nodes and returns the concatenated text as a
// string. This is useful because we can't use slot.textContent as an alternative.
//
export function getTextContent(slot: HTMLSlotElement): string {
	const nodes = slot ? slot.assignedNodes({ flatten: true }) : [];
	let text = "";

	[...nodes].map((node) => {
		if (node.nodeType === Node.TEXT_NODE) {
			text += node.textContent;
		}
	});

	return text;
}

//
// Determines whether an element has a slot. If name is specified, the function will look for a corresponding named
// slot, otherwise it will look for a "default" slot (e.g. a non-empty text node or an element with no slot attribute).
//
export function hasSlot(el: HTMLElement, name?: string) {
	// Look for a named slot
	if (name) {
		return el.querySelector(`[slot="${name}"]`) !== null;
	}

	// Look for a default slot
	return Array.from(el.childNodes).some((node) => {
		if (node.nodeType === node.TEXT_NODE && node.textContent.trim() !== "") {
			return true;
		}

		if (node.nodeType === node.ELEMENT_NODE) {
			const el = node as HTMLElement;
			if (!el.hasAttribute("slot")) {
				return true;
			}
		}

		return false;
	});
}

export function hasNamedSlot(hostEl, name: string) {
	return hostEl.querySelector(`:scope > [slot="${name}"]`) !== null;
}

export function hasDefaultSlot(hostEl) {
	return [...hostEl.childNodes].some((node) => {
		if (node.nodeType === node.TEXT_NODE && node.textContent?.trim() !== "") {
			return true;
		}

		if (node.nodeType === node.ELEMENT_NODE) {
			const el = node as HTMLElement;
			const tagName = el.tagName.toLowerCase();

			// Ignore visually hidden elements since they aren't rendered
			if (tagName === "hbr-visually-hidden") {
				return false;
			}

			// If it doesn't have a slot attribute, it's part of the default slot
			if (!el.hasAttribute("slot")) {
				return true;
			}
		}

		return false;
	});
}

export function testSlot(slotName: string, hostEl) {
	return slotName === "[default]"
		? hasDefaultSlot(hostEl)
		: hasNamedSlot(hostEl, slotName);
}
